(function () {
  'use strict';
  const TARGET = Object.freeze({
    group: '197124767711219',
    member: '61580630981781',
    author: 'VETRA ออกแบบ สร้าง เว็บไซต์',
    groupName: 'สร้างเว็บไซต์สร้างเพจขายของออนไลน์',
    url: 'https://www.facebook.com/groups/197124767711219/user/61580630981781/',
  });
  const ARTICLE = '[role="article"][aria-posinset]';
  const MENU_LABELS = new Set([
    'การดำเนินการสำหรับโพสต์นี้โดย ' + TARGET.author,
    'Actions for this post by ' + TARGET.author,
  ]);
  const DELETE_ITEMS = new Set(['Delete post', 'ลบโพสต์']);
  const DELETE_TITLES = new Set(['Delete post?', 'ลบโพสต์ใช่ไหม', 'ลบโพสต์ใช่ไหม?']);
  const DELETE_BUTTONS = new Set(['Delete', 'Delete post', 'ลบ', 'ลบโพสต์']);
  const normalize = (value) =>
    String(value || '')
      .replace(/\s+/g, ' ')
      .trim();
  function facebookUrl(href) {
    try {
      const url = new URL(href, 'https://www.facebook.com');
      return url.protocol === 'https:' &&
        ['www.facebook.com', 'facebook.com'].includes(url.hostname) &&
        !url.username &&
        !url.password &&
        !url.port
        ? url
        : null;
    } catch {
      return null;
    }
  }
  function isTargetRoute(href) {
    const url = facebookUrl(href);
    return (
      !!url &&
      url.pathname.replace(/\/$/, '') === '/groups/' + TARGET.group + '/user/' + TARGET.member
    );
  }
  function postIdFromHref(href) {
    const url = facebookUrl(href);
    const match = url?.pathname.match(/^\/groups\/(\d+)\/(?:posts|permalink)\/(\d+)\/?$/);
    return match && match[1] === TARGET.group ? match[2] : null;
  }
  function own(article, selector) {
    return [...article.querySelectorAll(selector)].filter(
      (node) => node.closest('[role="article"]') === article,
    );
  }
  function articleIdentity(article) {
    if (!article.matches(ARTICLE) || article.parentElement?.closest('[role="article"]'))
      return null;
    const anchors = own(article, 'a[href]');
    const ids = new Set(anchors.map((a) => postIdFromHref(a.getAttribute('href'))).filter(Boolean));
    if (ids.size !== 1 || !anchors.some((a) => isTargetRoute(a.getAttribute('href')))) return null;
    // Reject mixed group-post identities, including another group's embedded share.
    if (
      anchors.some((a) => {
        const url = facebookUrl(a.getAttribute('href'));
        return (
          /\/groups\/[^/]+\/(?:posts|permalink)\//.test(url?.pathname || '') &&
          !postIdFromHref(url.href)
        );
      })
    )
      return null;
    const menus = own(article, '[role="button"][aria-haspopup="menu"]').filter((node) =>
      MENU_LABELS.has(normalize(node.getAttribute('aria-label'))),
    );
    if (menus.length !== 1) return null;
    const id = [...ids][0];
    return {
      id,
      url: 'https://www.facebook.com/groups/' + TARGET.group + '/posts/' + id + '/',
      article,
      menu: menus[0],
    };
  }
  function uniqueNew(before, current) {
    const found = current.filter((node) => !before.has(node));
    if (found.length !== 1) throw new Error('Expected exactly one newly opened control; stopped.');
    return found[0];
  }
  function dialogIsDeletePost(dialog) {
    const headings = [...dialog.querySelectorAll('h1,h2,h3,[role="heading"]')];
    const titles = headings.map((node) => normalize(node.textContent));
    const label = normalize(dialog.getAttribute('aria-label'));
    if (label) titles.push(label);
    if (!titles.some((title) => DELETE_TITLES.has(title))) return false;
    return !/\b(?:ban|block|remove member|suspend|report)\b|แบน|บล็อก|ลบสมาชิก|นำสมาชิกออก|ระงับสมาชิก|รายงาน/i.test(
      dialog.textContent || '',
    );
  }
  function canStartRemoval(state, typed) {
    return (
      state.ready === true &&
      state.busy === false &&
      state.stopped === false &&
      Number.isSafeInteger(state.count) &&
      state.count > 0 &&
      typed === 'DELETE ' + state.count
    );
  }
  function createPacer(check, random = Math.random) {
    let stopped = false;
    const pending = new Set();
    return {
      stop() {
        stopped = true;
        for (const cancel of [...pending]) cancel();
