    const menus = () => [...doc.querySelectorAll('[role="menu"]')].filter(visible);
    const root = doc.createElement('section');
    root.id = 'vetra-group-cleanup-panel';
    root.style.cssText =
      'position:fixed;right:12px;top:12px;z-index:2147483647;width:min(360px,calc(100vw - 24px));max-height:85vh;overflow:auto;padding:16px;background:#17202e;color:#edf2ff;border:1px solid #9fb3df;border-radius:12px;font:14px/1.5 system-ui;box-shadow:0 8px 30px #0007;';
